{
  "case_id": "xsu_sg_009_medical_documentation_content",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "not_met",
      "reason": "Svaret formulerer indholdet som, hvad der \"bør\" og er \"nyttigt\", og ikke som krav. Det er en væsentlig fejl, fordi kilden siger, at oplysningerne skal fremsendes, hvis de er tilgængelige i journalen. Svaret nævner heller ikke, at dokumentationen skal være aktuel, og at den som minimum skal omfatte journaler. Desuden er det en tilføjelse, at fokus \"først og fremmest\" er mulighed for lønnet arbejde ved siden af uddannelsen. Det svarer ikke til kilden, hvor erhvervsevne kun skal beskrives \"hvis muligt\"."
    },
    "c02_required_elements_complete": {
      "label": "not_met",
      "reason": "Svaret dækker diagnose, forløb, påvirkning og behandling. Det mangler flere kritiske elementer: kravet om relevant og aktuel dokumentation, den varige funktionsnedsættelses art og grad, planlagt behandling (kun \"igangværende eller afprøvet\" nævnes) og udredningsforløb. Det mangler også, at oplysningerne skal fremsendes, når de er tilgængelige i journalen eller anden eksisterende lægefaglig dokumentation."
    },
    "c03_direct_relevance": {
      "label": "met",
      "reason": "Svaret handler direkte om, hvad den lægelige dokumentation skal beskrive, og indeholder ikke irrelevant tekst i stedet for et svar."
    },
    "c04_source_traceability": {
      "label": "not_met",
      "reason": "Svaret angiver ingen identificerbar kilde som bestemmelse eller vejledning. Det henviser kun generelt til \"SU's aktuelle vejledning\"."
    },
    "c05_source_validity": {
      "label": "not_assessable",
      "reason": "Der er ikke angivet nogen kilde, så gyldigheden kan ikke vurderes."
    },
    "c06_claim_source_support": {
      "label": "not_assessable",
      "reason": "Der er ikke angivet nogen kilde, så det kan ikke vurderes, om kilderne understøtter påstandene."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "not_met",
      "reason": "Svaret fremhæver mødestabilitet, arbejdstid og krav om tempo eller fleksibilitet. Det beskriver også bivirkninger, prognose og samlet virkning af flere helbredsproblemer som indhold. Det nævner endvidere, at \"en diagnose alene normalt ikke er nok\", og at det er \"først og fremmest\" påvirkningen af lønnet arbejde, som dokumentationen skal beskrive. Materialet støtter ikke disse udsagn som krav eller vægtning. Udsagnet om, at lægen ikke behøver konkludere om ret til tillægget, har heller ikke støtte i det givne materiale."
    },
    "c08_qualifications_and_exceptions": {
      "label": "not_met",
      "reason": "Svaret bevarer ikke forbeholdene \"hvis stillet\" (diagnose) og \"hvis planlagt\" for behandling. Det nævner ikke tilgængelighedsforbeholdet om journalen eller anden eksisterende dokumentation. Forbeholdet om erhvervsevne \"hvis muligt\" er vendt til hovedfokus."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "Svaret er internt sammenhængende, og dets konklusioner følger af de rammer, det selv opstiller. Det indeholder ingen indbyrdes modstridende trin."
    },
    "c10_legal_modality_precision": {
      "label": "not_met",
      "reason": "Svaret gengiver kildens \"skal\" som \"bør\" og \"nyttigt\", så obligatoriske oplysninger fremstår som valgfrie. Det omtaler heller ikke, at oplysningerne skal fremsendes, når de er tilgængelige. Det svarer til fejlen om, at foreliggende relevant dokumentation blot er valgfri at indsende."
    }
  },
  "xhaile_coverage": {
    "A39": {
      "label": "partial",
      "reason": "Svaret nævner \"Diagnose og forløb\" men ikke forbeholdet \"hvis der er stillet en\". Det siger dog, at en diagnose alene ikke er nok."
    },
    "A41": {
      "label": "yes",
      "reason": "Svaret beskriver, hvordan tilstanden har udviklet sig, og behandling, effekt og prognose. Det dækker i praksis sygdomsforløbet."
    },
    "A42": {
      "label": "yes",
      "reason": "Svaret nævner igangværende eller afprøvet behandling, effekt og bivirkninger."
    },
    "A45": {
      "label": "no",
      "reason": "Svaret nævner ikke planlagt behandling, kun igangværende eller afprøvet behandling og forventninger til varighed."
    },
    "A47": {
      "label": "partial",
      "reason": "Svaret dækker påvirkningen af mulighed for lønnet arbejde, men fremstiller det som det primære og ikke som \"hvis muligt\"."
    }
  },
  "overall_notes": "Svaret er relevant og dækker en del af indholdet i praksis. Det er dog for blødt formuleret: \"bør\" og \"nyttigt\" i stedet for \"skal\". Det udelader aktualitetskravet, planlagt behandling, art og grad, udredningsforløb samt tilgængelighedsforbeholdet. Det bevarer heller ikke forbeholdene \"hvis stillet\" og \"hvis muligt\". Svaret angiver ingen konkret kilde, så C04 er not_met, og C05 og C06 er not_assessable."
}

